export interface Rpc_Debug_RunProfiler {
}

export interface Rpc_Debug_RunProfiler_Request {
  /** 0 = save heap snapshot only; >0 = run timed profiler (CPU, heap, goroutines) for this many seconds. Set includeTrace to also capture the runtime execution trace. */
  durationInSeconds: number;
  reason: Rpc_Debug_RunProfiler_Request_Reason;
  /** Optional free-form description to attach to the profile */
  reasonDesc: string;
  /** Also capture the runtime execution trace (runtime/trace). Off by default: it is the heaviest artifact in both archive size and runtime overhead. Only applies when durationInSeconds > 0. */
  includeTrace: boolean;
}

export enum Rpc_Debug_RunProfiler_Request_Reason {
  UNKNOWN = 0,
  /** USER_REQUEST - Triggered explicitly by the user */
  USER_REQUEST = 1,
  /**
   * MEMORY_PRESSURE_WARN - iOS: DISPATCH_MEMORYPRESSURE_WARN
   * Android: onTrimMemory(RUNNING_LOW)
   */
  MEMORY_PRESSURE_WARN = 2,
  /**
   * MEMORY_PRESSURE_CRITICAL - iOS: DISPATCH_MEMORYPRESSURE_CRITICAL / applicationDidReceiveMemoryWarning
   * Android: onTrimMemory(RUNNING_CRITICAL)
   */
  MEMORY_PRESSURE_CRITICAL = 3,
  /**
   * THERMAL_SERIOUS - iOS: ProcessInfo.thermalState == .serious
   * Android: THERMAL_STATUS_SEVERE
   */
  THERMAL_SERIOUS = 4,
  /**
   * THERMAL_CRITICAL - iOS: ProcessInfo.thermalState == .critical
   * Android: THERMAL_STATUS_CRITICAL or higher
   */
  THERMAL_CRITICAL = 5,
  UNRECOGNIZED = -1,
}

