function createBaseRpc(): Rpc {
  return {};
}

export const Rpc: MessageFns<Rpc> = {
  encode(_: Rpc, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): Rpc {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseRpc();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  create<I extends Exact<DeepPartial<Rpc>, I>>(base?: I): Rpc {
    return Rpc.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<Rpc>, I>>(_: I): Rpc {
    const message = createBaseRpc();
    return message;
  },
};

